    /** Planificador con red de seguridad: si la IA falla o no da accion y el personaje no se nego, se usa lo que el juego entiende de la orden. */
    public static List<AiJson.Act> plan(AiClient.Settings base, String npcId, String npcName, String status, String bio, String world, String playerMessage, String said, String lookedAt, String literal, String hintName) throws AiClient.AiException {
        List<AiJson.Act> got = List.of();
        AiClient.AiException err = null;
        try {
            got = ActionPlanner.planAi(base, npcId, npcName, status, bio, world, playerMessage, said, lookedAt, literal, hintName);
        }
        catch (AiClient.AiException e) {
            err = e;
        }
        if (got.isEmpty()) {
            List<AiJson.Act> det = ActionPlanner.fallback(npcId, playerMessage, said, hintName, err != null);
            if (!det.isEmpty()) {
                return det;
            }
        }
        if (err != null) {
            throw err;
        }
        return got;
    }

    private static List<AiJson.Act> fallback(String npcId, String message, String said, String hint, boolean failed) {
        try {
            if (Commitment.of(said) == Commitment.Stance.REFUSE) {
                return List.of();
            }
            OrderParser.Result r = OrderParser.parse(message);
            boolean vehicle = r.hasStep("ride") || r.hasStep("drive") || r.hasStep("dismount");
            OrderParser.Order o = r.first();
            boolean wanted = hint != null && !hint.isBlank();
            if (o == null && wanted) {
                o = OrderParser.parse(hint.replace('_', ' ')).first();
            }
            if (o == null || !(failed || wanted || vehicle)) {
                return List.of();
            }
            return List.of(new AiJson.Act(npcId, o.type(), o.arg(), o.amount(), o.then(), o.spec(), o.where(), o.fresh(), o.name(), o.steps()));
        }
        catch (RuntimeException e) {
            return List.of();
        }
    }
